($t$Senna auriculata$t$, $t$Senna auriculata$t$, $t$Fabaceae$t$, $t$Famiglia botanica: Fabaceae. Portamento: Tree. Altezza massima indicativa: 5 m.$t$, $j${"luce": "Pieno sole", "acqua": "Abbondante, terreno costantemente umido", "terreno": "Tollera terreno: sabbioso/leggero, medio, argilloso/pesante"}$j$::jsonb, ARRAY[$t$Scheda in bozza, importata automaticamente da Plants For A Future (pfaf.org): dati non verificati manualmente, da controllare prima di considerarli affidabili$t$, $t$Nome comune (inglese, fonte PFAF): Matara Tea. Tanner's cassia$t$, $t$Rischi segnalati dalla fonte (testo originale in inglese, non tradotto per non alterarne il significato): The plant contains poisonous substances[299 ]. The bark, flowers, and seeds contain pyrrolizidine alkaloids, suspected of hepatotoxic properties[310 ]. The stem bark is used to stupefy fish[299 ].$t$], $j${"irrigazione": {"primavera": null, "estate": null, "autunno": null, "inverno": null}, "concimazione": {"primavera": null, "estate": null, "autunno": null, "inverno": null}, "potatura": {"primavera": null, "estate": null, "autunno": null, "inverno": null}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Fabaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": [], "resistenza_gelo": "bassa", "spaziatura_cm": null, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": null, "dimensione_minima_litri": null, "rinvaso_ogni_mesi": null, "irrigazione_fattore": null}$j$::jsonb, $t$perenne$t$, $t$senna-auriculata$t$, ARRAY[$t$Plants For A Future (pfaf.org) — importazione bozza automatica, dati non verificati manualmente$t$], $t$bozza$t$, null, null),
